28	import org.springframework.stereotype.Service;
29	import org.springframework.transaction.support.TransactionSynchronization;
30	import org.springframework.transaction.support.TransactionSynchronizationManager;
31	
32	/**
33	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
34	 * so tests can assert side-effects by reading that file — the second test-assertion channel
35	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
36	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
37	 *
38	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
39	 * SYNC) so a test reads the record immediately.
40	 */
41	@Service
42	public class Audit {
43	
44	    private final Path file;
45	
46	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
47	        this.file = Path.of(path);
48	    }
49	
50	    /** Append one audit record. Tests assert the exact line(s) in the file. */
51	    public synchronized void record(String entry) {
52	        try {
53	            Path parent = file.toAbsolutePath().getParent();
54	            if (parent != null) {
55	                Files.createDirectories(parent);
56	            }
57	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
58	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
59	        } catch (IOException e) {
60	            throw new UncheckedIOException(e);
61	        }
62	    }
63	
64	    /**
65	     * Append one audit record once the current transaction commits, so a change that is refused or
66	     * rolled back writes nothing. Records outside a transaction are appended at once.
67	     */
68	    public void recordOnCommit(String entry) {
69	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
70	            record(entry);
71	            return;
72	        }
73	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
74	            @Override
75	            public void afterCommit() {
76	                record(entry);
77	            }
78	        });
79	    }
80	
81	    /** Truncate the audit file. */
82	    public synchronized void clear() {
83	        try {
84	            Files.deleteIfExists(file);
85	        } catch (IOException e) {
86	            throw new UncheckedIOException(e);
87	        }
88	    }
89	}
