496	        Rollups.Rollup before = rollups.take(sheetId);
497	        Person person = person(sheetId, personId);
498	        LocalDate dated = date != null ? date : sheets.today(sheetId);
499	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, money(amount), dated, clean(note)));
