508	        Rollups.Rollup before = rollups.take(sheetId);
509	        Claim claim = claim(sheetId, claimId);
510	        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note));
511	        Claim saved = claims.saveAndFlush(claim);
512	        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
