527	        // sheet are serialised: each sees the other's committed claim and number.
528	        Integer number = next == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
529	        Rollups.Rollup before = rollups.take(sheetId);
530	        Claim claim = claim(sheetId, claimId);
531	        if (!claim.getStatus().canBecome(next)) {
532	            throw new ResponseStatusException(HttpStatus.CONFLICT,
533	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
534	        }
