546	            claim.openedBy(user);
547	        }
548	        if (next == ClaimStatus.SETTLED) {
549	            claim.settleDue(claim.isStated() ? claim.getStatedDue() : dues.live(claim, person.getGrade()));
550	        }
551	        Claim saved = claims.saveAndFlush(claim);
552	        String event = switch (next) {
553	            case OPEN -> "CLAIM_OPENED";
554	            case SETTLED -> "CLAIM_SETTLED";
555	            case VOID -> "CLAIM_VOIDED";
556	            case DRAFT -> throw new IllegalStateException();
