602	package net.officefloor.hq.app.claim;
603	
604	/**
605	 * A claim's status: DRAFT when added; a DRAFT claim may be opened, an OPEN one settled, and a DRAFT
606	 * or OPEN one voided. SETTLED and VOID are final. Only OPEN and SETTLED claims count.
607	 */
608	public enum ClaimStatus {
609	    DRAFT, OPEN, SETTLED, VOID;
610	
611	    /** Whether a claim may move from this status to {@code next}. */
612	    public boolean canBecome(ClaimStatus next) {
613	        return switch (next) {
614	            case OPEN -> this == DRAFT;
615	            case SETTLED -> this == OPEN;
616	            case VOID -> this == DRAFT || this == OPEN;
617	            case DRAFT -> false;
618	        };
619	    }
620	
621	    /** Whether a claim in this status counts toward what is claimed and due. */
622	    public boolean counts() {
623	        return this == OPEN || this == SETTLED;
624	    }
625	}
