630	import java.math.RoundingMode;
631	import net.officefloor.hq.app.rate.Rate;
632	import net.officefloor.hq.app.rate.RateRepository;
633	import org.springframework.stereotype.Component;
634	
635	/** What is due on a claim, read from the rates its person's grade has. */
636	@Component
637	public class Dues {
638	
639	    private final RateRepository rates;
640	
641	    public Dues(RateRepository rates) {
642	        this.rates = rates;
643	    }
644	
645	    /**
646	     * The due figure a claim shows: the one fixed when it was settled, else the one its person's last
647	     * statement bound it to, else its amount at the rate the grade has in force on the claim's date;
648	     * null (n/a) when there is none.
649	     */
650	    public BigDecimal figure(Claim claim, String grade) {
651	        if (claim.getSettledDue() != null) {
652	            return claim.getSettledDue();
653	        }
654	        return claim.isStated() ? claim.getStatedDue() : live(claim, grade);
655	    }
656	
657	    /** A claim's amount at the rate the grade has in force on the claim's date; null when it has none. */
658	    public BigDecimal live(Claim claim, String grade) {
659	        return rates.findInForce(claim.getSheetId(), grade, claim.getDate())
660	                .map(rate -> due(claim.getAmount(), rate))
661	                .orElse(null);
662	    }
663	
664	    /** What is due on an amount at a rate: the amount times the percent over 100, rounded half to even. */
665	    private static BigDecimal due(BigDecimal amount, Rate rate) {
666	        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
667	    }
668	}
