1292	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
1293	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1294	            if (claim.getStatus().counts()) {
1295	                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
1296	            }
