1609	import org.springframework.http.HttpStatus;
1610	import org.springframework.stereotype.Service;
1611	import org.springframework.transaction.annotation.Transactional;
1612	import org.springframework.web.server.ResponseStatusException;
1613	
1614	/**
1615	 * A person's statements: taking one records their due-total on the sheet's today, binds each of
1616	 * their counting claims to the due figure it shows then, and leaves the rest unbound.
1617	 */
1618	@Service
1619	public class StatementService {
1620	
1621	    /** Shown in place of a due-total when the grade has no rate. */
1622	    private static final String NO_RATE = "n/a";
1623	
1624	    /** The person as stated, with all of their claims, newest first. */
1625	    public record Stated(Person person, List<Claim> claims) {
1626	    }
1627	
1628	    private final PersonRepository people;
1629	    private final ClaimRepository claims;
1630	    private final ClaimService claimService;
1631	    private final RateRepository rates;
1632	    private final SheetService sheets;
1633	    private final Rollups rollups;
1634	    private final Audit audit;
1635	
1636	    public StatementService(PersonRepository people, ClaimRepository claims, ClaimService claimService,
1637	            RateRepository rates, SheetService sheets, Rollups rollups, Audit audit) {
1638	        this.rollups = rollups;
1639	        this.people = people;
1640	        this.claims = claims;
1641	        this.claimService = claimService;
1642	        this.rates = rates;
1643	        this.sheets = sheets;
1644	        this.audit = audit;
1645	    }
1646	
1647	    /** Take a statement for a person on the sheet. */
1648	    @Transactional
1649	    public Stated take(String sheetId, String user, long personId) {
1650	        LocalDate today = sheets.today(sheetId);
1651	        Person person = people.findByIdAndSheetId(personId, sheetId)
1652	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
1653	        Rollups.Rollup before = rollups.take(sheetId);
1654	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
1655	        BigDecimal total = BigDecimal.ZERO.setScale(2);
1656	        boolean fixed = false;
1657	        int counted = 0;
1658	        for (Claim claim : theirs) {
1659	            if (!claim.getStatus().counts()) {
1660	                claim.unbind();
1661	                continue;
1662	            }
1663	            BigDecimal figure = claimService.figure(claim, person.getGrade());
1664	            fixed |= figure != null && (claim.getSettledDue() != null || claim.isStated());
1665	            claim.bind(figure);
1666	            counted++;
1667	            if (figure != null) {
1668	                total = total.add(figure);
1669	            }
1670	        }
1671	        // As on the screen: n/a when the grade has no rate today, unless a claim keeps a fixed figure.
1672	        if (rates.findInForce(sheetId, person.getGrade(), today).isEmpty() && !fixed) {
1673	            total = null;
1674	        }
1675	        person.stated(total, today);
1676	        Person saved = people.saveAndFlush(person);
1677	        List<Claim> bound = claims.saveAllAndFlush(theirs);
1678	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
1679	                + " due-total=" + (total != null ? total.toPlainString() : NO_RATE) + " claims=" + counted);
1680	        rollups.audit(sheetId, user, before);
1681	        return new Stated(saved, bound);
1682	    }
